function updateLanguageSwitcherDisplay(e){const t=document.querySelector('.lakum-language-switcher a');if(!t)return;const a=t.querySelector('.lakum-lang-text');'ar'===e?(a.textContent='EN',t.setAttribute('title','Switch to English')):(a.textContent='AR',t.setAttribute('title','التبديل إلى العربية'))}document.addEventListener('DOMContentLoaded',function(){const e=document.querySelector('.lakum-language-switcher a');e&&(updateLanguageSwitcherDisplay(window.LAKUM_LANG||'en'),e.addEventListener('click',function(e){}))});
